---@type VoicePackConfig
local VoicePackConfig = T(Global, "VoicePackConfig")

---@param player SBasePlayer
function GMHelper:getAllVoicePack(player)
    for _, cfg in pairs(VoicePackConfig:getAllCfgs()) do
        player.voicePackData:addVoicePack(cfg.id)
    end
end

---@param player SBasePlayer
function GMHelper:removeAllVoicePack(player)
    for _, cfg in pairs(VoicePackConfig:getAllCfgs()) do
        player.voicePackData:removeVoicePack(cfg.id)
    end
end